import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

conv3d_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void conv3d_kxk1_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    const int batch_size,
    const int in_channels,
    const int out_channels,
    const int D_in, const int H_in, const int W_in,
    const int D_out, const int H_out, const int W_out,
    const int kD, const int kH, const int kW,
    const int stride,
    const int padding,
    const int dilation,
    const int groups,
    const int in_channels_per_group,
    const int out_channels_per_group,
    const bool has_bias)
{
    long total = (long)batch_size * out_channels * D_out * H_out * W_out;
    long idx = blockIdx.x * (long)blockDim.x + threadIdx.x;
    long stride_grid = (long)blockDim.x * gridDim.x;

    for (; idx < total; idx += stride_grid) {
        long tmp = idx;
        int ow = tmp % W_out; tmp /= W_out;
        int oh = tmp % H_out; tmp /= H_out;
        int od = tmp % D_out; tmp /= D_out;
        int oc = tmp % out_channels; tmp /= out_channels;
        int n = tmp;

        int g = oc / out_channels_per_group;
        int ic_start = g * in_channels_per_group;

        float acc = 0.0f;

        for (int icl = 0; icl < in_channels_per_group; icl++) {
            int ic = ic_start + icl;

            for (int kd = 0; kd < kD; kd++) {
                int id = od * stride - padding + kd * dilation;
                if (id < 0 || id >= D_in) continue;

                for (int kh = 0; kh < kH; kh++) {
                    int ih = oh * stride - padding + kh * dilation;
                    if (ih < 0 || ih >= H_in) continue;

                    for (int kw = 0; kw < kW; kw++) {
                        int iw = ow * stride - padding + kw * dilation;
                        if (iw < 0 || iw >= W_in) continue;

                        long input_idx = (((long)n * in_channels + ic) * D_in + id) * H_in * W_in
                                          + (long)ih * W_in + iw;

                        long weight_idx = ((((long)oc * in_channels_per_group + icl) * kD + kd) * kH + kh) * kW + kw;

                        acc += input[input_idx] * weight[weight_idx];
                    }
                }
            }
        }

        if (has_bias) {
            acc += bias[oc];
        }

        long output_idx = (((long)n * out_channels + oc) * D_out + od) * H_out * W_out
                           + (long)oh * W_out + ow;
        output[output_idx] = acc;
    }
}

torch::Tensor conv3d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int dilation,
    int groups,
    bool has_bias)
{
    input = input.contiguous();
    weight = weight.contiguous();
    if (has_bias) {
        bias = bias.contiguous();
    }

    const int batch_size = input.size(0);
    const int in_channels = input.size(1);
    const int D_in = input.size(2);
    const int H_in = input.size(3);
    const int W_in = input.size(4);

    const int out_channels = weight.size(0);
    const int in_channels_per_group = weight.size(1);
    const int kD = weight.size(2);
    const int kH = weight.size(3);
    const int kW = weight.size(4);

    const int out_channels_per_group = out_channels / groups;

    const int D_out = (D_in + 2 * padding - dilation * (kD - 1) - 1) / stride + 1;
    const int H_out = (H_in + 2 * padding - dilation * (kH - 1) - 1) / stride + 1;
    const int W_out = (W_in + 2 * padding - dilation * (kW - 1) - 1) / stride + 1;

    auto output = torch::empty({batch_size, out_channels, D_out, H_out, W_out}, input.options());

    long total = (long)batch_size * out_channels * D_out * H_out * W_out;
    const int threads = 256;
    long blocks = (total + threads - 1) / threads;
    if (blocks > 65535 * 1024L) blocks = 65535 * 1024L; // safety cap, grid-stride handles rest
    if (blocks < 1) blocks = 1;

    const float* bias_ptr = has_bias ? bias.data_ptr<float>() : nullptr;

    conv3d_kxk1_kernel<<<(unsigned int)blocks, threads>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        batch_size,
        in_channels,
        out_channels,
        D_in, H_in, W_in,
        D_out, H_out, W_out,
        kD, kH, kW,
        stride,
        padding,
        dilation,
        groups,
        in_channels_per_group,
        out_channels_per_group,
        has_bias);

    return output;
}
"""

conv3d_cpp_source = r"""
torch::Tensor conv3d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int dilation,
    int groups,
    bool has_bias);
"""

conv3d_module = load_inline(
    name="conv3d_kxk1",
    cpp_sources=conv3d_cpp_source,
    cuda_sources=conv3d_source,
    functions=["conv3d_forward"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Performs a standard 3D convolution operation with an asymmetric input and a square kernel,
    using a custom CUDA kernel for the forward pass.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1,
                 padding: int = 0, dilation: int = 1, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.dilation = dilation
        self.groups = groups
        self.has_bias = bias

        # Weight shape: (out_channels, in_channels/groups, kernel_size, kernel_size, 1)
        self.weight = nn.Parameter(
            torch.empty(out_channels, in_channels // groups, kernel_size, kernel_size, 1)
        )
        nn.init.kaiming_uniform_(self.weight, a=5 ** 0.5)

        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
            fan_in = (in_channels // groups) * kernel_size * kernel_size * 1
            bound = 1 / (fan_in ** 0.5)
            nn.init.uniform_(self.bias, -bound, bound)
        else:
            self.register_parameter('bias', None)

        self.conv3d_module = conv3d_module

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.cuda().contiguous()
        weight = self.weight.cuda()
        if self.has_bias:
            bias = self.bias.cuda()
        else:
            bias = torch.empty(0, device=x.device, dtype=x.dtype)

        return self.conv3d_module.conv3d_forward(
            x, weight, bias,
            self.stride, self.padding, self.dilation, self.groups, self.has_bias
        )


